<script setup>
import { computed, ref, onMounted } from 'vue'
import { ArrowUpRight, FileCheck2, Clock3, Wallet, Building2, ArrowRight, ShieldCheck, Users, CreditCard, Landmark, ArrowLeftRight, Zap, Contact, Smartphone, HandCoins, DollarSign, RefreshCw, Plus } from 'lucide-vue-next'
import { api, get, money, label, message } from '../services/api'
import StatusBadge from '../components/StatusBadge.vue'
const props = defineProps({ data: Object, clients: Array, can: Function })
const emit = defineEmits(['navigate', 'action', 'open', 'refresh'])
const maximum = computed(() => Math.max(1, ...(props.data?.por_estado || []).map(x => x.cantidad)))
// External API: reference exchange rate (Banco de Guatemala).
const rate = ref(null), collecting = ref(false), collection = ref(null), collectionError = ref('')
onMounted(async () => { try { rate.value = await get('/tipo-cambio') } catch { rate.value = { disponible: false } } })
async function collect() {
  collecting.value = true; collectionError.value = ''
  try { collection.value = (await api.post('/cobros/ejecutar')).data.data; emit('refresh') } catch (e) { collectionError.value = message(e) } finally { collecting.value = false }
}
const summary = computed(() => { const c = collection.value; if (!c) return ''; const all = [...c.prestamos, ...c.tarjetas]; return all.length ? `${all.filter(x => x.resultado === 'cobrado').length} cobrados por completo, ${all.filter(x => x.resultado === 'parcial').length} parciales y ${all.filter(x => x.resultado === 'sin_fondos').length} sin fondos.` : 'No había cuotas ni estados de cuenta por cobrar hoy.' })
// Registry tiles: totals Gestiones administers as the core of the three systems.
const registry = computed(() => { const g = props.data?.global; if (!g) return []; return [
  { key:'clientes', icon:Users, tone:'blue', title:'Clientes', value:g.clientes, detail:`${g.clientes_con_app} con acceso a Banca Virtual` },
  { key:'clientes', icon:Smartphone, tone:'teal', title:'Sesiones activas en la app', value:g.sesiones_app_activas, detail:'Credenciales administradas en Gestiones' },
  { key:'cuentas', icon:Wallet, tone:'teal', title:'Cuentas', value:g.cuentas_ahorro + g.cuentas_monetarias, detail:`${g.cuentas_ahorro} de ahorro · ${g.cuentas_monetarias} monetarias${g.cuentas_bloqueadas ? ` · ${g.cuentas_bloqueadas} bloqueadas` : ''}` },
  { key:'cuentas', icon:Landmark, tone:'blue', title:'Saldos de clientes', value:money(g.saldo_ahorro_centavos + g.saldo_monetario_centavos), detail:`Ahorro ${money(g.saldo_ahorro_centavos)} · Monetario ${money(g.saldo_monetario_centavos)}` },
  { key:'creditos', icon:HandCoins, tone:'amber', title:'Cartera de préstamos', value:money(g.cartera_prestamos_centavos), detail:`${g.prestamos_vigentes} vigentes${g.cuotas_vencidas ? ` · ${g.cuotas_vencidas} cuota(s) vencida(s)` : ' · al día'}` },
  { key:'tarjetas', icon:CreditCard, tone:'violet', title:'Tarjetas', value:g.tarjetas_credito + g.tarjetas_debito, detail:`Límite otorgado ${money(g.limite_credito_centavos)} · Deuda ${money(g.deuda_tarjetas_centavos)}` },
  { key:'movimientos', icon:ArrowLeftRight, tone:'teal', title:'Movimientos de hoy', value:g.movimientos_hoy, detail:`Volumen ${money(g.volumen_hoy_centavos)}` },
  { key:'movimientos', icon:Zap, tone:'amber', title:'Pagos de servicios', value:g.pagos_servicios, detail:`Total pagado ${money(g.pagos_servicios_centavos)}` },
  { key:'colaboradores', icon:Contact, tone:'violet', title:'Banca corporativa', value:g.empresas, detail:`${g.colaboradores} colaboradores en planilla` },
] })
const customer = id => props.clients.find(x => (x.id || x._id) === id)?.nombre || 'Cliente registrado'
</script>
<template>
  <div v-if="data" class="dashboard">
    <section class="overview-intro"><div><p class="eyebrow">UNA VISTA DE TODA LA OPERACIÓN</p><h2>Todo listo para seguir avanzando.</h2><p>Atiende las gestiones que los clientes envían desde Banca Virtual.</p></div><span class="inbox-note">Las gestiones llegan desde Banca Virtual</span></section>
    <section class="metrics">
      <article class="metric"><div class="metric-top"><span>Gestiones registradas</span><span class="metric-icon blue"><FileCheck2 :size="20"/></span></div><strong>{{ data.solicitudes }}</strong><small>Recibidas desde Banca Virtual <ArrowUpRight :size="14"/></small></article>
      <article class="metric"><div class="metric-top"><span>Por aprobar</span><span class="metric-icon amber"><Clock3 :size="20"/></span></div><strong>{{ data.pendientes }}<span class="metric-suffix">gestiones</span></strong><small>En evaluación, esperando tu aprobación</small></article>
      <article class="metric"><div class="metric-top"><span>Cuenta concentradora</span><span class="metric-icon teal"><Landmark :size="20"/></span></div><strong class="amount">{{ money(data.concentradora?.saldo_centavos) }}</strong><small>Bóveda del banco · salió {{ money(data.concentradora?.salidas_centavos) }} · entró {{ money(data.concentradora?.entradas_centavos) }}</small><button v-if="can('concentradora.fondear')" class="text-button vault-fund" @click="$emit('action','ingreso-concentradora')"><Plus :size="15"/>Ingresar fondos</button></article>
      <article class="metric"><div class="metric-top"><span>Tipo de cambio</span><span class="metric-icon violet"><DollarSign :size="20"/></span></div><p v-if="rate?.quetzales_por_dolar" class="rate-line"><span>1 Dólar (USD) =</span></p><strong class="amount">{{ rate?.disponible === false ? '—' : rate ? `Q ${Number(rate.quetzales_por_dolar).toFixed(4)}` : '…' }}<span v-if="rate?.quetzales_por_dolar" class="metric-suffix">Quetzales (GTQ)</span></strong><small>{{ rate?.disponible === false ? 'Servicio externo sin respuesta' : rate ? `Tipo de cambio de referencia · ${rate.fuente} · ${rate.fecha}${rate.desactualizado ? ' (último conocido)' : ''}` : 'Consultando al Banco de Guatemala…' }}</small></article>
    </section>
    <div class="dashboard-grid"><section class="panel recent-panel"><div class="panel-heading"><div><h3>Gestiones recientes</h3><p>Últimas gestiones recibidas</p></div><button class="text-button" @click="$emit('navigate', 'solicitudes')">Ver todas <ArrowRight :size="16"/></button></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>CLIENTE / GESTIÓN</th><th>PRODUCTO</th><th>ESTADO</th><th></th></tr></thead><tbody><tr v-for="item in data.recientes" :key="item.id" class="clickable-row" @click="$emit('open', item)"><td><div class="person-cell"><span class="avatar">{{ customer(item.cliente_id).slice(0, 2).toUpperCase() }}</span><span><b>{{ customer(item.cliente_id) }}</b><small>{{ item.folio }}</small></span></div></td><td data-label="PRODUCTO">{{ label(item.producto) }}</td><td data-label="ESTADO"><StatusBadge :value="item.estado"/></td><td class="cell-action"><button class="icon-button" aria-label="Ver solicitud" @click.stop="$emit('open', item)"><ArrowUpRight :size="18"/></button></td></tr><tr v-if="!data.recientes.length"><td colspan="4" class="empty-inline">Aún no hay gestiones. Llegarán cuando los clientes las envíen desde Banca Virtual.</td></tr></tbody></table></div></section>
    <section class="panel distribution"><div class="panel-heading"><div><h3>Flujo de gestiones</h3><p>Distribución por etapa</p></div><span class="small-tag">RESUMEN</span></div><div class="bars"><div v-for="item in data.por_estado" :key="item.estado"><div class="bar-label"><span>{{ label(item.estado) }}</span><b>{{ item.cantidad }}</b></div><div class="bar-track"><span :class="item.estado" :style="{width: `${item.cantidad / maximum * 100}%`}"></span></div></div></div><div class="distribution-footer"><ShieldCheck :size="18"/><span><b>{{ data.emitidas }} gestiones emitidas</b><small>{{ data.planillas_pendientes }} planilla(s) por autorizar</small></span></div>
      <div v-if="can('cobros.run')" class="collection-box"><b>Cobros automáticos</b><small>Cuotas de préstamo y estados de cuenta de tarjeta vencidos se debitan cada día a las 18:00. Puedes ejecutarlos ahora.</small><button class="secondary" :disabled="collecting" @click="collect"><RefreshCw :size="15" :class="{spinning:collecting}"/>{{ collecting ? 'Cobrando…' : 'Ejecutar cobros ahora' }}</button><p v-if="summary" class="muted">{{ summary }}</p><p v-if="collectionError" class="error-text">{{ collectionError }}</p></div></section></div>
    <section v-if="data.concentradora?.por_tipo?.length" class="panel vault-panel"><div class="panel-heading"><div><h3>Movimientos de la cuenta concentradora</h3><p>Todo el dinero del banco que salió hacia clientes y empresas, y lo que regresó. Inició con {{ money(data.concentradora.fondos_iniciales_centavos) }}.</p></div><span class="small-tag">PARTIDA DOBLE</span></div><div class="vault-rows"><div v-for="row in data.concentradora.por_tipo" :key="row.tipo"><span>{{ label(row.tipo) }}</span><b v-if="row.salidas_centavos" class="negative">− {{ money(row.salidas_centavos) }}</b><b v-if="row.entradas_centavos" class="positive">+ {{ money(row.entradas_centavos) }}</b></div></div></section>
    <section class="registry-section"><div><h3>Registro global del banco</h3><p>Todo lo que CP Gestiones centraliza como sistema principal. Haz clic para ver el detalle.</p></div><div class="registry-grid"><button v-for="tile in registry" :key="tile.title" class="registry-tile" @click="$emit('navigate', tile.key)"><span class="metric-icon" :class="tile.tone"><component :is="tile.icon" :size="18"/></span><span><small>{{ tile.title }}</small><b>{{ tile.value }}</b><em>{{ tile.detail }}</em></span></button></div></section>
    <section class="quick-section"><div><h3>Operaciones frecuentes</h3><p>Continúa con una gestión del día a día.</p></div><div class="quick-actions"><button v-if="can('clientes.write')" @click="$emit('action', 'clientes')"><span class="metric-icon blue"><Users :size="20"/></span><span><b>Registrar cliente</b><small>Con acceso a Banca y cuenta</small></span><ArrowUpRight :size="19"/></button><button v-if="can('dinero.write')" @click="$emit('action', 'transferencia')"><span class="metric-icon teal"><ArrowRight :size="20"/></span><span><b>Transferir fondos</b><small>Entre cuentas del banco</small></span><ArrowUpRight :size="19"/></button><button v-if="can('planillas.write')" @click="$emit('action', 'planillas')"><span class="metric-icon violet"><Building2 :size="20"/></span><span><b>Cargar una planilla</b><small>Se paga al autorizarla</small></span><ArrowUpRight :size="19"/></button></div></section>
  </div>
</template>
